{"thought": "<clinical reasoning>", "final_answer": [{"quadrant": <1-4>, "tooth_position": <1-8>, "diagnosis": "<Caries|Deep Caries|Periapical Lesion|Impacted Tooth>", "confidence": <0.0-1.0>}, ...]}

